+      content.push({
+        type: "file",
+        file: { filename: attachment.name, file_data: `data:application/pdf;base64,${attachmentData(attachment)}` },
+      });
+    } else {
+      content.push({ type: "text", text: textAttachmentBlock(attachment) });
+    }
+  }
+  return content;
+}
